function minReorder(n, connections) {
  const adj = Array.from({ length: n }, () => []);
  for (const [u, v] of connections) {
    adj[u].push([v, 1]); // original direction (outward from 0 = needs flip)
    adj[v].push([u, 0]); // inward toward 0 = no flip needed
  }
  let changes = 0;
  const visited = new Set([0]);
  const q = [0];
  while (q.length > 0) {
    const curr = q.shift();
    for (const [neighbor, cost] of adj[curr]) {
      if (!visited.has(neighbor)) {
        visited.add(neighbor);
        changes += cost;
        q.push(neighbor);
      }
    }
  }
  return changes;
}

