  let changes = 0;
  function dfs(curr, parent) {
    for (const [next, cost] of adj[curr]) {
      if (next !== parent) {
        changes += cost;
        dfs(next, curr);
      }
    }
  }
  dfs(0, -1);
  return changes;
}

