function snakesAndLadders(board) {
  const n = board.length;
  const dist = new Array(n * n + 1).fill(Infinity);
  dist[1] = 0;
  const q = [1];
  function getPos(s) {
    const r = n - 1 - Math.floor((s - 1) / n);
    const rem = (s - 1) % n;
    const c = (Math.floor((s - 1) / n) % 2 === 0) ? rem : n - 1 - rem;
    return [r, c];
  }
  while (q.length > 0) {
    const u = q.shift();
    if (u === n * n) return dist[u];
    for (let k = 1; k <= 6 && u + k <= n * n; k++) {
      let v = u + k;
      const [r, c] = getPos(v);
      if (board[r][c] !== -1) v = board[r][c];
      if (dist[v] > dist[u] + 1) {
        dist[v] = dist[u] + 1;
        q.push(v);
      }
    }
  }
  return -1;
}

