function minKnightMoves(x, y) {
  x = Math.abs(x);
  y = Math.abs(y);
  const memo = new Map();
  function dfs(cx, cy) {
    if (cx + cy === 0) return 0;
    if (cx + cy === 2) return 2;
    const key = `${cx},${cy}`;
    if (memo.has(key)) return memo.get(key);
    const ans = Math.min(
      dfs(Math.abs(cx - 1), Math.abs(cy - 2)),
      dfs(Math.abs(cx - 2), Math.abs(cy - 1))
    ) + 1;
    memo.set(key, ans);
    return ans;
  }
  return dfs(x, y);
}

