function minKnightMoves(x, y) {
  x = Math.abs(x);
  y = Math.abs(y);
  const queue = [[0, 0, 0]];
  const visited = new Set(['0,0']);
  const dirs = [
    [1, 2], [2, 1], [-1, 2], [-2, 1],
    [1, -2], [2, -1], [-1, -2], [-2, -1]
  ];
  let head = 0;
  while (head < queue.length) {
    const [cx, cy, steps] = queue[head++];
    if (cx === x && cy === y) return steps;
    for (const [dx, dy] of dirs) {
      const nx = cx + dx, ny = cy + dy;
      if (nx >= -1 && ny >= -1 && nx <= x + 2 && ny <= y + 2) {
        const key = `${nx},${ny}`;
        if (!visited.has(key)) {
          visited.add(key);
          queue.push([nx, ny, steps + 1]);
        }
      }
    }
  }
  return 0;
}

