  const n = graph.length;
  const color = new Array(n).fill(0);
  function dfs(u, c) {
    color[u] = c;
    for (const v of graph[u]) {
      if (color[v] === c) return false;
      if (color[v] === 0 && !dfs(v, -c)) return false;
    }
    return true;
  }
  for (let i = 0; i < n; i++) {
    if (color[i] === 0 && !dfs(i, 1)) return false;
  }
  return true;
}
